// Qué cita va a qué calendario, y con qué clave se la reconoce.
//
// - El calendario es el del EMPLEADO del recurso que atiende (`primary`), y solo si
//   ha activado "Sincronizar calendario", está activo y tiene email. Sin eso, la cita
//   no tiene evento -- y si lo tenía, se borra.
// - La clave es el id de la cita. En una clase en grupo (recurso con capacidad > 1)
//   es la de la CLASE: recurso + hora + servicio. Una clase de 10 es un evento con
//   la lista de apuntados, no diez eventos encima unos de otros.
//
// Un fallo de Directus para el workflow a la vista: seguir con una lista vacía
// borraría eventos que sí existen.
const r = $json ?? {};
if (!(r.statusCode >= 200 && r.statusCode < 300)) {
  throw new Error('Directus devolvió ' + r.statusCode + ' al leer las citas pendientes: '
    + JSON.stringify(r.body).slice(0, 300));
}
const filas = (r.body && r.body.data) || [];
if (!filas.length) return [];

const citas = filas.map((a) => {
  const rec = Array.isArray(a.recursos) ? a.recursos : [];
  const prim = rec.find((x) => x.role === 'primary') || rec[0] || null;
  const res = (prim && prim.resource_id) || null;
  const emp = (res && res.employee_id) || null;
  const grupo = !!(res && Number(res.capacity) > 1);
  const inicio = a.start_at ? DateTime.fromISO(a.start_at, { zone: 'utc' }).toISO() : '';
  const servicio = (a.service_id && a.service_id.id) || '';
  const buzon = (emp && emp.sincronizar_calendario === true
    && String(emp.status || '').toLowerCase() === 'active' && emp.email)
    ? String(emp.email).trim().toLowerCase() : null;
  return {
    id: a.id, updated_at: a.updated_at, status: a.status, start_at: a.start_at, end_at: a.end_at,
    title: a.title, notes: a.notes, servicio: (a.service_id && a.service_id.name) || a.title || 'Cita',
    servicio_id: servicio, contacto: a.contact_id || null,
    recurso_id: res ? res.id : null, recurso: res ? res.name : null,
    grupo, buzon,
    clave: grupo ? `grupo:${res.id}|${inicio}|${servicio}` : a.id,
  };
});

const grupos = [];
const vistos = new Set();
for (const c of citas) {
  if (c.grupo && !vistos.has(c.clave)) {
    vistos.add(c.clave);
    grupos.push({ recurso_id: c.recurso_id, start_at: c.start_at, servicio_id: c.servicio_id });
  }
}
return [{ json: { citas, claves: [...new Set(citas.map((c) => c.clave))], grupos } }];

// Para cada clave, qué hay que hacer en Outlook para que el calendario diga lo mismo
// que Aegora. Se recalcula desde cero en cada pasada, así que marcar de más no hace
// daño y una pasada fallida se arregla sola en la siguiente.
//
//   crear       hay que tener evento y no lo hay
//   actualizar  lo hay, en el buzón que toca: se reescribe
//   mover       lo hay, pero en OTRO buzón (cambió quién atiende): se borra y se crea
//   borrar      lo hay y ya no debe (cancelada, o el empleado desactivó la sincronización)
//   nada        ni lo hay ni debe haberlo
//   esperar     la última vez falló hace menos de 15 min: no se insiste cada minuto
//               contra un buzón que no existe; la cita sigue pendiente
const leer = (nombre) => {
  const r = $(nombre).first().json ?? {};
  if (!(r.statusCode >= 200 && r.statusCode < 300)) {
    throw new Error(nombre + ': Directus devolvió ' + r.statusCode + ' '
      + JSON.stringify(r.body).slice(0, 300));
  }
  return (r.body && r.body.data) || [];
};
const { citas } = $('Code · Claves').first().json;
const filas = leer('HTTP · Filas de sincronización');
const asistentes = leer('HTTP · Asistentes de clases');
const filaDe = Object.fromEntries(filas.map((f) => [f.clave, f]));
const ACTIVAS = ['scheduled', 'confirmed'];
const ESPERA_TRAS_ERROR_MS = 15 * 60 * 1000;

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (ch) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const nombre = (ct) => [ct && ct.first_name, ct && ct.last_name].filter(Boolean).join(' ')
  || (ct && ct.company) || 'Cliente';
const telefono = (ct) => ((ct && ct.phones) || []).map((p) => p.phone_number).filter(Boolean)[0] || '';
const utc = (s) => DateTime.fromISO(s, { zone: 'utc' }).toFormat("yyyy-LL-dd'T'HH:mm:ss");
// Va en todos los eventos: en esta fase el calendario es un espejo, y un cambio hecho
// en Outlook no vuelve a Aegora. Sin decirlo, alguien movería la cita en el móvil y
// el cliente seguiría citado a la hora de antes.
const PIE = '<p style="color:#6b7280;font-size:12px">Reservada con Aegora. Para cambiarla o '
  + 'anularla, hazlo en el panel de Aegora: lo que se cambie aquí no llega al cliente.</p>';

const evento = (c, apuntados) => {
  let subject, content;
  if (apuntados) {
    const n = apuntados.length;
    subject = `${c.servicio} · ${n} ${n === 1 ? 'apuntado' : 'apuntados'}`;
    content = '<p><b>Apuntados:</b></p><ul>' + apuntados.map((a) => {
      const ct = a.contact_id || {};
      const extra = [ct.company, telefono(ct)].filter(Boolean).map(esc).join(' · ');
      return `<li>${esc(nombre(ct))}${extra ? ' — ' + extra : ''}</li>`;
    }).join('') + '</ul>' + PIE;
  } else {
    const ct = c.contacto || {};
    subject = `${c.servicio} · ${nombre(ct)}`;
    const lineas = [['Cliente', nombre(ct)], ['Empresa', ct.company], ['Teléfono', telefono(ct)]]
      .filter(([, v]) => v).map(([k, v]) => `<b>${k}:</b> ${esc(v)}`).join('<br>');
    content = `<p>${lineas}</p>` + (c.notes ? `<p>${esc(c.notes).replace(/\n/g, '<br>')}</p>` : '') + PIE;
  }
  return {
    subject,
    body: { contentType: 'HTML', content },
    start: { dateTime: utc(c.start_at), timeZone: 'UTC' },
    end: { dateTime: utc(c.end_at), timeZone: 'UTC' },
    showAs: 'busy',
    categories: ['Aegora'],
    isReminderOn: true,
    reminderMinutesBeforeStart: 15,
  };
};

const ops = new Map();
for (const c of citas) {
  if (!ops.has(c.clave)) ops.set(c.clave, { c, desmarcar: [] });
  ops.get(c.clave).desmarcar.push({ id: c.id, updated_at: c.updated_at });
}

const salida = [];
for (const [clave, { c, desmarcar }] of ops) {
  const fila = filaDe[clave] || null;
  let quiere = null;
  if (c.grupo) {
    const apuntados = asistentes.filter((a) => a.start_at === c.start_at && a.service_id === c.servicio_id
      && (a.recursos || []).some((x) => x.resource_id === c.recurso_id && x.role === 'primary'));
    if (c.buzon && apuntados.length) quiere = evento(c, apuntados);
  } else if (c.buzon && ACTIVAS.includes(c.status)) {
    quiere = evento(c, null);
  }

  const tiene = !!(fila && fila.external_event_id);
  let op;
  if (fila && fila.estado === 'error' && fila.date_updated
      && Date.now() - DateTime.fromISO(fila.date_updated).toMillis() < ESPERA_TRAS_ERROR_MS) op = 'esperar';
  else if (quiere && !tiene) op = 'crear';
  else if (quiere && fila.buzon === c.buzon) op = 'actualizar';
  else if (quiere) op = 'mover';
  else if (tiene) op = 'borrar';
  else op = 'nada';

  salida.push({ json: {
    op, clave, desmarcar,
    buzon: c.buzon,
    buzon_anterior: fila ? fila.buzon : null,
    event_id: fila ? fila.external_event_id : null,
    fila_id: fila ? fila.id : null,
    // transactionId: si Graph recibe dos veces la misma creación (un reintento), no
    // crea dos eventos.
    evento: quiere ? (op === 'crear' || op === 'mover' ? { ...quiere, transactionId: clave.slice(0, 200) } : quiere) : null,
  } });
}
return salida;

// Lo que respondió Microsoft, convertido en lo que hay que guardar. Se lee la
// operación del Plan por emparejamiento (`.item`): $json aquí es la respuesta de
// Graph, o el propio plan si no hubo nada que pedirle.
const op = $('Code · Plan').item.json;
const r = $json ?? {};
const code = r.statusCode || 0;
const bien = code >= 200 && code < 300;
const motivo = () => {
  const e = r.body && r.body.error;
  return (e ? `${e.code}: ${e.message}` : `HTTP ${code}`).slice(0, 500);
};

let ok = true;
let fila = null;
switch (op.op) {
  case 'crear':
  case 'mover':
    if (bien && r.body && r.body.id) {
      fila = { estado: 'sincronizada', external_event_id: r.body.id, buzon: op.buzon, error: null };
    } else {
      ok = false;
      fila = { estado: 'error', error: motivo(), buzon: op.buzon,
               external_event_id: op.op === 'mover' ? null : (op.event_id || null) };
    }
    break;
  case 'actualizar':
    if (bien) {
      fila = { estado: 'sincronizada', external_event_id: op.event_id, buzon: op.buzon, error: null };
    } else if (code === 404) {
      // Alguien lo borró a mano en Outlook. Se olvida y la siguiente pasada lo crea.
      ok = false;
      fila = { estado: 'sin_evento', external_event_id: null,
               error: 'El evento ya no estaba en Outlook; se vuelve a crear.' };
    } else {
      ok = false;
      fila = { estado: 'error', error: motivo() };
    }
    break;
  case 'borrar':
    // 404 también es éxito: el evento ya no está, que es lo que se quería.
    if (bien || code === 404) fila = { estado: 'sin_evento', external_event_id: null, error: null };
    else { ok = false; fila = { estado: 'error', error: motivo() }; }
    break;
  default:
    fila = null;
}

const guardar = !!fila;
return { json: {
  ...op,
  _ok: ok,
  _guardar: guardar,
  _fila_id: op.fila_id || null,
  _fila: guardar ? (op.fila_id ? fila : { clave: op.clave, proveedor: 'outlook', ...fila }) : null,
} };

// Las citas que ya están como deben quedan desmarcadas. Las que fallaron siguen
// marcadas y vuelven a entrar en la siguiente pasada.
//
// Se desmarca SOLO si la cita no ha cambiado desde que se leyó (mismo `updated_at`):
// si alguien la movió mientras se hablaba con Outlook, el cambio nuevo no se pierde.
// Y si guardar la fila falló, tampoco: se crearía otro evento la próxima vez.
const base = $('Config (editar por tenant)').first().json.directus_base_url;
const salida = [];
$input.all().forEach((it, i) => {
  const r = $('Code · Resultado').itemMatching(i).json;
  const code = it.json && it.json.statusCode;
  const guardada = code === undefined || (code >= 200 && code < 300);
  if (!r._ok || !guardada) return;
  for (const d of r.desmarcar) salida.push({ json: { ...d, directus_base_url: base } });
});
return salida;
